previewCss:
.darma-loader-darma-b9-confetti-fall { --accent: var(--loader-color, #f472b6); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; overflow: hidden; }
.darma-loader-darma-b9-confetti-fall span { position: absolute; top: -12%; width: calc(var(--loader-size, 80px) * .06); height: calc(var(--loader-size, 80px) * .11); border-radius: 2px; background: var(--accent); animation: darma-loader-darma-b9-confetti-fall-fall calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b9-confetti-fall span:nth-child(even) { background: var(--accent-2); }
.darma-loader-darma-b9-confetti-fall span:nth-child(1) { left: 12%; animation-delay: 0s; }
.darma-loader-darma-b9-confetti-fall span:nth-child(2) { left: 30%; animation-delay: calc(var(--loader-speed, 1s) * .5); }
.darma-loader-darma-b9-confetti-fall span:nth-child(3) { left: 48%; animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-darma-b9-confetti-fall span:nth-child(4) { left: 64%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b9-confetti-fall span:nth-child(5) { left: 80%; animation-delay: calc(var(--loader-speed, 1s) * 1.3); }
.darma-loader-darma-b9-confetti-fall span:nth-child(6) { left: 90%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
@keyframes darma-loader-darma-b9-confetti-fall-fall { 0% { transform: translateY(0) rotate(0deg); opacity: 0; } 12% { opacity: 1; } 88% { opacity: 1; } 100% { transform: translateY(calc(var(--loader-size, 80px) * 1.15)) rotate(400deg); opacity: 0; } }

